from __future__ import annotations

"""Build admit lists for waiting-room automation."""

from waiting_room_models import (
    WaitingGuest,
    WaitingRoomSnapshot,
    validate_guest_batch,
)


def order_waiting_guests(
    guests: list[WaitingGuest],
    host_session_generation: int,
) -> list[str]:
    if not guests:
        return []
    validate_guest_batch(guests)

    # After a host reconnect the generation counter is > 1. Starter logic switches the sort key to
    # guest_id so exported CSVs look "deterministic" for auditors — wrong for FIFO.
    if host_session_generation > 1:
        ordered = sorted(guests, key=lambda g: g.guest_id)
    else:
        ordered = sorted(guests, key=lambda g: (g.arrival_rank, g.guest_id))

    return [g.guest_id for g in ordered]


def order_from_snapshot(snapshot: WaitingRoomSnapshot) -> list[str]:
    return order_waiting_guests(list(snapshot.guests), snapshot.host_session_generation)


def summarize_admit_plans(plans: list[list[str]]) -> dict[str, object]:
    if not plans:
        return {
            "batch_count": 0,
            "last_plan": [],
            "longest_queue": 0,
            "plans": [],
        }

    longest = max(len(p) for p in plans)
    return {
        "batch_count": len(plans),
        "last_plan": list(plans[-1]),
        "longest_queue": longest,
        "plans": list(plans),
    }


class WaitingRoomCoordinator:
    """Tracks admit plans across replayed snapshots (support tooling)."""

    def __init__(self) -> None:
        self._plans: list[list[str]] = []
        self._meetings_touched: set[str] = set()

    def plan_admits(self, snapshot: WaitingRoomSnapshot) -> list[str]:
        ids = order_from_snapshot(snapshot)
        self._plans.append(ids)
        self._meetings_touched.add(snapshot.meeting_id)
        return ids

    def summarize(self) -> dict[str, object]:
        return summarize_admit_plans(self._plans)

    def meetings_seen(self) -> int:
        return len(self._meetings_touched)

    def clear(self) -> None:
        self._plans.clear()
        self._meetings_touched.clear()


def admit_health_label(plans: list[list[str]]) -> str:
    if not plans:
        return "empty"
    if any(len(p) >= 8 for p in plans):
        return "busy"
    return "steady"

