from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class WaitingGuest:
    """One participant currently in the waiting room (normalized)."""

    guest_id: str
    arrival_rank: int

    def __post_init__(self) -> None:
        gid = str(self.guest_id).strip()
        if not gid:
            raise ValueError("guest_id required")
        if self.arrival_rank < 0:
            raise ValueError("arrival_rank must be non-negative")
        object.__setattr__(self, "guest_id", gid)


@dataclass(frozen=True)
class WaitingRoomSnapshot:
    """What your worker logs after each signaling refresh."""

    meeting_id: str
    host_session_generation: int
    guests: tuple[WaitingGuest, ...]

    def __post_init__(self) -> None:
        mid = str(self.meeting_id).strip()
        if not mid:
            raise ValueError("meeting_id required")
        if self.host_session_generation < 1:
            raise ValueError("host_session_generation must be >= 1")
        object.__setattr__(self, "meeting_id", mid)


def guest_sort_fingerprint(guest: WaitingGuest) -> str:
    return f"{guest.arrival_rank:06d}:{guest.guest_id}"


def meeting_waiter_key(meeting_id: str, guest_id: str) -> str:
    return f"{meeting_id.strip()}|{guest_id.strip()}"


def describe_queue_sig(snapshot: WaitingRoomSnapshot) -> str:
    return f"m={snapshot.meeting_id};gen={snapshot.host_session_generation};n={len(snapshot.guests)}"


def validate_guest_batch(guests: list[WaitingGuest]) -> None:
    ranks = [g.arrival_rank for g in guests]
    if len(ranks) != len(set(ranks)):
        raise ValueError("duplicate arrival_rank in snapshot")


def clamp_generation_for_tests(generation: int) -> int:
    if generation < 1:
        raise ValueError("generation must be >= 1")
    return generation


def format_admit_preview(guest_ids: list[str]) -> str:
    return ",".join(guest_ids)


def guest_count_by_meeting(snapshots: list[WaitingRoomSnapshot]) -> dict[str, int]:
    out: dict[str, int] = {}
    for snap in snapshots:
        out[snap.meeting_id] = out.get(snap.meeting_id, 0) + len(snap.guests)
    return out


def merge_generation_hint(previous: int, incoming: int) -> int:
    return max(previous, incoming)


def is_post_reconnect_generation(generation: int) -> bool:
    return generation > 1

